Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
Lemma land_highmask : forall x j, 0 <= j < 64 -> 0 <= x < 2 ^ 64 ->
  Z.land x (2 ^ 64 - 2 ^ j) = x - x mod 2 ^ j.
Proof.
