Section VP147. Context {fx : FPState}.   (* [comment removed for export] *)
Lemma and_mask_id : forall (v : word) j,
  (0 <= j)%Z -> (j < 64)%Z -> (bv_unsigned v mod 2 ^ j = 0)%Z ->
