Section VP154. Context {fx : FPState}.   (* [comment removed for export] *)
Lemma and_lowmask_zero : forall (v : word) j,
  (0 <= j)%Z -> (j <= 64)%Z -> (2 ^ j | bv_unsigned v)%Z ->
